package com.skillingcost;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;

/**
 * Pure cost math: given a method, an action count, and a price map, computes input costs,
 * output revenue, GE tax, and net gp. No I/O and no Swing, so it is easy to unit test.
 *
 * Missing prices (untradeable or unfetched items) are treated as 0 gp rather than failing.
 */
final class CostCalculator
{
    /** GE tax parameters, snapshotted from config at calculation time. */
    static final class TaxSettings
    {
        private final int basisPoints;
        private final int capGp;
        private final int exemptBelowGp;

        TaxSettings(int basisPoints, int capGp, int exemptBelowGp)
        {
            this.basisPoints = basisPoints;
            this.capGp = capGp;
            this.exemptBelowGp = exemptBelowGp;
        }
    }

    private CostCalculator()
    {
    }

    /** Net gp (sell revenue - tax - input cost) without building display lines. */
    static long estimateNet(
        SkillingMethod method,
        long actionsNeeded,
        boolean includeOptionalInputs,
        boolean sellOutputs,
        boolean includeTax,
        Map<Integer, WikiPrice> prices,
        TaxSettings tax)
    {
        long inputCost = 0;
        for (ItemQuantity input : method.getRequiredInputs())
        {
            inputCost += buyTotal(input, actionsNeeded, prices);
        }
        if (includeOptionalInputs)
        {
            for (ItemQuantity input : method.getOptionalInputs())
            {
                inputCost += buyTotal(input, actionsNeeded, prices);
            }
        }

        long outputGross = 0;
        long taxTotal = 0;
        if (sellOutputs)
        {
            for (ItemQuantity output : method.getOutputs())
            {
                int unitSell = sellUnitPrice(output, prices);
                long quantity = output.getTotalQuantity(actionsNeeded);
                outputGross += quantity * unitSell;
                taxTotal += includeTax ? geTax(unitSell, quantity, tax) : 0;
            }
        }

        return outputGross - taxTotal - inputCost;
    }

    /** Full breakdown with per-item display lines for the result panel. */
    static CostResult buildResult(
        SkillingMethod method,
        int currentLevel,
        int currentXp,
        int targetLevel,
        int targetXp,
        int xpNeeded,
        long actionsNeeded,
        boolean includeOptionalInputs,
        boolean sellOutputs,
        boolean includeTax,
        Map<Integer, WikiPrice> prices,
        TaxSettings tax)
    {
        long inputCost = 0;
        long outputGross = 0;
        long taxTotal = 0;
        long newestPriceTimestamp = 0;
        List<String> requiredInputLines = new ArrayList<>();
        List<String> optionalInputLines = new ArrayList<>();
        List<String> outputLines = new ArrayList<>();

        for (ItemQuantity input : method.getRequiredInputs())
        {
            inputCost += appendInputLine(input, actionsNeeded, prices, requiredInputLines, false);
            newestPriceTimestamp = Math.max(newestPriceTimestamp, priceTimestamp(input, prices));
        }
        if (includeOptionalInputs)
        {
            for (ItemQuantity input : method.getOptionalInputs())
            {
                inputCost += appendInputLine(input, actionsNeeded, prices, optionalInputLines, true);
                newestPriceTimestamp = Math.max(newestPriceTimestamp, priceTimestamp(input, prices));
            }
        }

        if (sellOutputs)
        {
            for (ItemQuantity output : method.getOutputs())
            {
                int unitSell = sellUnitPrice(output, prices);
                long quantity = output.getTotalQuantity(actionsNeeded);
                long lineTotal = quantity * unitSell;
                outputGross += lineTotal;
                taxTotal += includeTax ? geTax(unitSell, quantity, tax) : 0;
                outputLines.add(Formats.itemLine(output.getName(), quantity, unitSell, lineTotal));
                newestPriceTimestamp = Math.max(newestPriceTimestamp, priceTimestamp(output, prices));
            }
        }

        long net = outputGross - taxTotal - inputCost;

        return new CostResult(
            method,
            currentLevel,
            currentXp,
            targetLevel,
            targetXp,
            xpNeeded,
            actionsNeeded,
            inputCost,
            outputGross,
            taxTotal,
            net,
            requiredInputLines,
            optionalInputLines,
            outputLines,
            includeOptionalInputs,
            sellOutputs,
            newestPriceTimestamp);
    }

    /**
     * GE tax for one output line. Items whose unit price is below the exemption threshold are
     * tax free; otherwise tax is {@code basisPoints/10000} of the price, capped per item.
     */
    static long geTax(int unitSellPrice, long quantity, TaxSettings tax)
    {
        if (unitSellPrice < tax.exemptBelowGp)
        {
            return 0;
        }
        long taxPerItem = ((long) unitSellPrice * tax.basisPoints) / 10_000L;
        taxPerItem = Math.min(taxPerItem, tax.capGp);
        return taxPerItem * quantity;
    }

    private static long appendInputLine(
        ItemQuantity item,
        long actionsNeeded,
        Map<Integer, WikiPrice> prices,
        List<String> lines,
        boolean optional)
    {
        int unitBuy = buyUnitPrice(item, prices);
        long quantity = item.getTotalQuantity(actionsNeeded);
        long total = quantity * unitBuy;
        String name = optional ? item.getName() + " (optional)" : item.getName();
        lines.add(Formats.itemLine(name, quantity, unitBuy, total));
        return total;
    }

    private static long buyTotal(ItemQuantity item, long actionsNeeded, Map<Integer, WikiPrice> prices)
    {
        return item.getTotalQuantity(actionsNeeded) * (long) buyUnitPrice(item, prices);
    }

    private static int buyUnitPrice(ItemQuantity item, Map<Integer, WikiPrice> prices)
    {
        if (item.hasFixedUnitPrice())
        {
            return item.getFixedUnitPrice();
        }
        WikiPrice price = prices.get(item.getItemId());
        return price == null ? 0 : price.getInstantBuyPrice();
    }

    private static int sellUnitPrice(ItemQuantity item, Map<Integer, WikiPrice> prices)
    {
        if (item.hasFixedUnitPrice())
        {
            return item.getFixedUnitPrice();
        }
        WikiPrice price = prices.get(item.getItemId());
        return price == null ? 0 : price.getInstantSellPrice();
    }

    private static long priceTimestamp(ItemQuantity item, Map<Integer, WikiPrice> prices)
    {
        if (item.hasFixedUnitPrice())
        {
            return 0;
        }
        WikiPrice price = prices.get(item.getItemId());
        return price == null ? 0 : price.getNewestTimestamp();
    }
}

package com.skillingcost;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

final class CostResult
{
    private final SkillingMethod method;
    private final int currentLevel;
    private final int currentXp;
    private final int targetLevel;
    private final int targetXp;
    private final int xpNeeded;
    private final long actionsNeeded;
    private final long inputCost;
    private final long outputGross;
    private final long tax;
    private final long net;
    private final List<String> requiredInputLines;
    private final List<String> optionalInputLines;
    private final List<String> outputLines;
    private final boolean includeOptionalInputs;
    private final boolean sellOutputs;
    private final long newestPriceTimestamp;

    CostResult(
        SkillingMethod method,
        int currentLevel,
        int currentXp,
        int targetLevel,
        int targetXp,
        int xpNeeded,
        long actionsNeeded,
        long inputCost,
        long outputGross,
        long tax,
        long net,
        List<String> requiredInputLines,
        List<String> optionalInputLines,
        List<String> outputLines,
        boolean includeOptionalInputs,
        boolean sellOutputs,
        long newestPriceTimestamp
    )
    {
        this.method = method;
        this.currentLevel = currentLevel;
        this.currentXp = currentXp;
        this.targetLevel = targetLevel;
        this.targetXp = targetXp;
        this.xpNeeded = xpNeeded;
        this.actionsNeeded = actionsNeeded;
        this.inputCost = inputCost;
        this.outputGross = outputGross;
        this.tax = tax;
        this.net = net;
        this.requiredInputLines = new ArrayList<>(requiredInputLines);
        this.optionalInputLines = new ArrayList<>(optionalInputLines);
        this.outputLines = new ArrayList<>(outputLines);
        this.includeOptionalInputs = includeOptionalInputs;
        this.sellOutputs = sellOutputs;
        this.newestPriceTimestamp = newestPriceTimestamp;
    }

    SkillingMethod getMethod()
    {
        return method;
    }

    int getCurrentLevel()
    {
        return currentLevel;
    }

    int getCurrentXp()
    {
        return currentXp;
    }

    int getTargetLevel()
    {
        return targetLevel;
    }

    int getTargetXp()
    {
        return targetXp;
    }

    int getXpNeeded()
    {
        return xpNeeded;
    }

    long getActionsNeeded()
    {
        return actionsNeeded;
    }

    long getInputCost()
    {
        return inputCost;
    }

    long getOutputGross()
    {
        return outputGross;
    }

    long getTax()
    {
        return tax;
    }

    long getNet()
    {
        return net;
    }

    List<String> getRequiredInputLines()
    {
        return Collections.unmodifiableList(requiredInputLines);
    }

    List<String> getOptionalInputLines()
    {
        return Collections.unmodifiableList(optionalInputLines);
    }

    List<String> getOutputLines()
    {
        return Collections.unmodifiableList(outputLines);
    }

    boolean isIncludeOptionalInputs()
    {
        return includeOptionalInputs;
    }

    boolean isSellOutputs()
    {
        return sellOutputs;
    }

    long getNewestPriceTimestamp()
    {
        return newestPriceTimestamp;
    }
}

package com.skillingcost;

import net.runelite.api.Skill;

/** Small text-formatting helpers shared by the plugin and panel. */
final class Formats
{
    private Formats()
    {
    }

    /** Formats a gp amount with thousands separators, e.g. {@code -12,345 gp}. */
    static String gp(long value)
    {
        String sign = value < 0 ? "-" : "";
        return sign + String.format("%,d gp", Math.abs(value));
    }

    /** Compact gp for narrow UI spots, e.g. {@code -82.3M gp}, {@code 15.2K gp}, {@code 950 gp}. */
    static String gpCompact(long value)
    {
        String sign = value < 0 ? "-" : "";
        long abs = Math.abs(value);
        if (abs >= 1_000_000_000L)
        {
            return sign + String.format("%.2fB gp", abs / 1_000_000_000.0);
        }
        if (abs >= 1_000_000L)
        {
            return sign + String.format("%.1fM gp", abs / 1_000_000.0);
        }
        if (abs >= 10_000L)
        {
            return sign + String.format("%.0fK gp", abs / 1_000.0);
        }
        return sign + String.format("%,d gp", abs);
    }

    /** {@code Skill.RUNECRAFT} -&gt; {@code "Runecraft"}. */
    static String skillName(Skill skill)
    {
        String text = skill.name().toLowerCase().replace('_', ' ');
        StringBuilder out = new StringBuilder();
        boolean nextUpper = true;
        for (int i = 0; i < text.length(); i++)
        {
            char c = text.charAt(i);
            if (nextUpper && Character.isLetter(c))
            {
                out.append(Character.toUpperCase(c));
                nextUpper = false;
            }
            else
            {
                out.append(c);
            }
            if (c == ' ')
            {
                nextUpper = true;
            }
        }
        return out.toString();
    }

    /** Three display lines for one priced item: quantity x name, unit price, line total. */
    static String itemLine(String name, long quantity, int unitPrice, long total)
    {
        return String.format("%,d × %s", quantity, name)
            + "\n" + String.format("%,d gp each", unitPrice)
            + "\n" + gp(total) + " total";
    }
}

package com.skillingcost;

/**
 * An item and how much of it one action consumes or produces.
 *
 * Quantities may be fractional (e.g. one jug of wine covering many libation offerings); the
 * total over a calculation is rounded per {@code roundUpTotal}. Items with a fixed unit price
 * (e.g. flat NPC fees, item id -1) skip the GE price lookup entirely.
 */
final class ItemQuantity
{
    private final int itemId;
    private final String name;
    private final double quantityPerAction;
    private final boolean roundUpTotal;
    private final int fixedUnitPrice;

    ItemQuantity(int itemId, String name, double quantityPerAction)
    {
        this(itemId, name, quantityPerAction, true);
    }

    ItemQuantity(int itemId, String name, double quantityPerAction, boolean roundUpTotal)
    {
        this(itemId, name, quantityPerAction, roundUpTotal, -1);
    }

    ItemQuantity(int itemId, String name, double quantityPerAction, boolean roundUpTotal, int fixedUnitPrice)
    {
        this.itemId = itemId;
        this.name = name;
        this.quantityPerAction = quantityPerAction;
        this.roundUpTotal = roundUpTotal;
        this.fixedUnitPrice = fixedUnitPrice;
    }

    int getItemId()
    {
        return itemId;
    }

    String getName()
    {
        return name;
    }

    double getQuantityPerAction()
    {
        return quantityPerAction;
    }

    boolean hasFixedUnitPrice()
    {
        return fixedUnitPrice >= 0;
    }

    int getFixedUnitPrice()
    {
        return fixedUnitPrice;
    }

    long getTotalQuantity(long actions)
    {
        double raw = actions * quantityPerAction;
        if (roundUpTotal)
        {
            return (long) Math.ceil(raw);
        }
        return Math.round(raw);
    }
}

package com.skillingcost;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * One row in the method list. Either a standalone method, or a group of variants (e.g. every
 * bone offered at a gilded altar) shown as a single row with a variant dropdown.
 */
final class MethodListEntry
{
    private final String displayName;
    private final List<SkillingMethod> variants;
    private int selectedVariantIndex;

    private MethodListEntry(String displayName, List<SkillingMethod> variants)
    {
        this.displayName = displayName;
        this.variants = variants;
    }

    /** Collapses a flat method list into rows, preserving order of first appearance. */
    static List<MethodListEntry> build(List<SkillingMethod> methods)
    {
        Map<String, List<SkillingMethod>> byGroup = new LinkedHashMap<>();
        List<MethodListEntry> entries = new ArrayList<>();
        // Placeholder inserted into 'entries' where each group first appears, replaced below.
        Map<String, Integer> groupPositions = new LinkedHashMap<>();

        for (SkillingMethod method : methods)
        {
            String group = method.getGroupName();
            if (group == null)
            {
                entries.add(new MethodListEntry(method.getName(), Collections.singletonList(method)));
                continue;
            }
            List<SkillingMethod> variants = byGroup.get(group);
            if (variants == null)
            {
                variants = new ArrayList<>();
                byGroup.put(group, variants);
                groupPositions.put(group, entries.size());
                entries.add(null);
            }
            variants.add(method);
        }

        for (Map.Entry<String, Integer> position : groupPositions.entrySet())
        {
            entries.set(position.getValue(),
                new MethodListEntry(position.getKey(), byGroup.get(position.getKey())));
        }
        return entries;
    }

    String getDisplayName()
    {
        return displayName;
    }

    boolean hasVariants()
    {
        return variants.size() > 1;
    }

    List<SkillingMethod> getVariants()
    {
        return Collections.unmodifiableList(variants);
    }

    SkillingMethod getSelected()
    {
        return variants.get(selectedVariantIndex);
    }

    int getSelectedVariantIndex()
    {
        return selectedVariantIndex;
    }

    void setSelectedVariantIndex(int index)
    {
        if (index >= 0 && index < variants.size())
        {
            selectedVariantIndex = index;
        }
    }

    /** Lowest level requirement across variants; used by the "hide locked" filter. */
    int getMinRequiredLevel()
    {
        int min = Integer.MAX_VALUE;
        for (SkillingMethod method : variants)
        {
            min = Math.min(min, method.getRequiredLevel());
        }
        return min;
    }

    @Override
    public String toString()
    {
        return displayName;
    }
}

package com.skillingcost;

import com.google.gson.Gson;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Skill;

/**
 * Loads and caches all skilling methods from the bundled {@code methods.json} resource.
 *
 * Most methods are listed verbatim in the JSON. Prayer is special-cased: the JSON only contains
 * a table of bones (bury XP + blessed bone shards) and ashes, and this class expands that table
 * into one method group per way of offering them (bury, gilded altar, chaos altar, Ectofuntus,
 * libation bowl with regular or sunfire wine, scatter). Adding a new bone to the JSON therefore
 * automatically adds it to every offering method.
 */
@Singleton
final class MethodRepository
{
    private static final String RESOURCE = "/methods.json";

    // Offering multipliers, all relative to bury XP. See e.g.
    // https://oldschool.runescape.wiki/w/Prayer#Bones
    private static final double GILDED_ALTAR_MULTIPLIER = 3.5;
    // Chaos altar offerings give gilded-altar XP with a 50% chance to not consume the bone,
    // so on average each bone consumed is worth double: 7x bury XP.
    private static final double CHAOS_ALTAR_MULTIPLIER = 7.0;
    private static final double ECTOFUNTUS_MULTIPLIER = 4.0;
    // Libation bowl XP is per blessed bone shard: 5 XP with blessed wine, 6 with sunfire wine.
    private static final double XP_PER_SHARD_WINE = 5.0;
    private static final double XP_PER_SHARD_SUNFIRE = 6.0;
    // Consumption rates carried over from the original hand-computed data:
    // one jug of wine per 400 shards, one batch of sunfire splinters per 200 shards.
    private static final double SHARDS_PER_JUG_OF_WINE = 400.0;
    private static final double SHARDS_PER_SUNFIRE_SPLINTER = 200.0;

    private final Gson gson;

    private List<Skill> supportedSkills;
    private Map<Skill, List<SkillingMethod>> methodsBySkill;

    @Inject
    MethodRepository(Gson gson)
    {
        this.gson = gson;
    }

    synchronized List<Skill> getSupportedSkills()
    {
        load();
        return supportedSkills;
    }

    /** Methods per skill, in display order. The returned lists must not be modified. */
    synchronized Map<Skill, List<SkillingMethod>> getMethodsBySkill()
    {
        load();
        return methodsBySkill;
    }

    private void load()
    {
        if (methodsBySkill != null)
        {
            return;
        }

        RootJson root;
        try (InputStream in = MethodRepository.class.getResourceAsStream(RESOURCE))
        {
            if (in == null)
            {
                throw new IllegalStateException("Missing bundled resource " + RESOURCE);
            }
            root = gson.fromJson(new InputStreamReader(in, StandardCharsets.UTF_8), RootJson.class);
        }
        catch (Exception e)
        {
            throw new IllegalStateException("Failed to load " + RESOURCE + ": " + e.getMessage(), e);
        }
        if (root == null || root.skills == null || root.methods == null || root.prayer == null)
        {
            throw new IllegalStateException(RESOURCE + " is malformed");
        }

        List<Skill> skills = new ArrayList<>();
        Map<Skill, List<SkillingMethod>> map = new LinkedHashMap<>();
        for (String skillName : root.skills)
        {
            Skill skill = Skill.valueOf(skillName);
            skills.add(skill);
            map.put(skill, new ArrayList<>());
        }

        for (MethodJson method : root.methods)
        {
            Skill skill = Skill.valueOf(method.skill);
            map.get(skill).add(new SkillingMethod(
                skill,
                method.name,
                method.group,
                method.variant,
                method.level,
                method.xp,
                toItems(method.inputs),
                toItems(method.optional),
                toItems(method.outputs)));
        }

        List<SkillingMethod> prayer = map.get(Skill.PRAYER);
        if (prayer != null)
        {
            prayer.addAll(expandPrayer(root.prayer));
        }

        for (Map.Entry<Skill, List<SkillingMethod>> entry : map.entrySet())
        {
            entry.setValue(Collections.unmodifiableList(entry.getValue()));
        }
        supportedSkills = Collections.unmodifiableList(skills);
        methodsBySkill = Collections.unmodifiableMap(map);
    }

    /** Expands the bones/ashes tables into full method groups. */
    private static List<SkillingMethod> expandPrayer(PrayerJson prayer)
    {
        List<SkillingMethod> methods = new ArrayList<>();

        for (BoneJson bone : prayer.bones)
        {
            methods.add(boneMethod("Bury", bone, bone.level, bone.buryXp,
                items(bone(bone))));
        }
        for (BoneJson bone : prayer.bones)
        {
            methods.add(boneMethod("Gilded altar (both burners lit)", bone, bone.level,
                bone.buryXp * GILDED_ALTAR_MULTIPLIER, items(bone(bone))));
        }
        for (BoneJson bone : prayer.bones)
        {
            methods.add(boneMethod("Chaos altar (avg. 50% bone save)", bone, bone.level,
                bone.buryXp * CHAOS_ALTAR_MULTIPLIER, items(bone(bone))));
        }
        for (BoneJson bone : prayer.bones)
        {
            methods.add(boneMethod("Ectofuntus", bone, bone.level,
                bone.buryXp * ECTOFUNTUS_MULTIPLIER,
                items(bone(bone), ref(prayer.bucketOfSlime, 1))));
        }
        for (BoneJson bone : prayer.bones)
        {
            methods.add(boneMethod("Libation bowl (blessed wine)", bone,
                Math.max(prayer.libationMinLevel, bone.level),
                bone.shards * XP_PER_SHARD_WINE,
                items(bone(bone), unnotingFee(prayer),
                    ref(prayer.jugOfWine, bone.shards / SHARDS_PER_JUG_OF_WINE))));
        }
        for (BoneJson bone : prayer.bones)
        {
            methods.add(boneMethod("Libation bowl (sunfire wine)", bone,
                Math.max(prayer.libationMinLevel, bone.level),
                bone.shards * XP_PER_SHARD_SUNFIRE,
                items(bone(bone), unnotingFee(prayer),
                    ref(prayer.jugOfWine, bone.shards / SHARDS_PER_JUG_OF_WINE),
                    ref(prayer.sunfireSplinters, bone.shards / SHARDS_PER_SUNFIRE_SPLINTER))));
        }

        for (AshJson ash : prayer.ashes)
        {
            methods.add(new SkillingMethod(Skill.PRAYER,
                "Scatter " + ash.name.toLowerCase(),
                "Scatter ashes", ash.name,
                ash.level, ash.scatterXp,
                items(new ItemQuantity(ash.id, ash.name, 1)),
                Collections.emptyList(), Collections.emptyList()));
        }

        return methods;
    }

    private static SkillingMethod boneMethod(String group, BoneJson bone, int level, double xp, List<ItemQuantity> inputs)
    {
        return new SkillingMethod(Skill.PRAYER,
            group + " - " + bone.name.toLowerCase(),
            group, bone.name,
            level, xp,
            inputs, Collections.emptyList(), Collections.emptyList());
    }

    private static ItemQuantity bone(BoneJson bone)
    {
        return new ItemQuantity(bone.id, bone.name, 1);
    }

    private static ItemQuantity ref(ItemRefJson item, double quantityPerAction)
    {
        return new ItemQuantity(item.id, item.name, quantityPerAction);
    }

    private static ItemQuantity unnotingFee(PrayerJson prayer)
    {
        // Virilis outside the libation altar un-notes bones for a flat gp fee per bone.
        return new ItemQuantity(-1, "Virilis unnoting fee", 1, true, prayer.libationFeeGp);
    }

    private static List<ItemQuantity> items(ItemQuantity... entries)
    {
        List<ItemQuantity> list = new ArrayList<>();
        Collections.addAll(list, entries);
        return list;
    }

    private static List<ItemQuantity> toItems(List<ItemJson> items)
    {
        List<ItemQuantity> out = new ArrayList<>();
        if (items == null)
        {
            return out;
        }
        for (ItemJson item : items)
        {
            if (item.fixedPrice != null)
            {
                out.add(new ItemQuantity(item.id, item.name, item.qty, true, item.fixedPrice));
            }
            else
            {
                out.add(new ItemQuantity(item.id, item.name, item.qty));
            }
        }
        return out;
    }

    // --- Gson DTOs mirroring methods.json ---

    private static final class RootJson
    {
        List<String> skills;
        List<MethodJson> methods;
        PrayerJson prayer;
    }

    private static final class MethodJson
    {
        String skill;
        String name;
        String group;
        String variant;
        int level;
        double xp;
        List<ItemJson> inputs;
        List<ItemJson> optional;
        List<ItemJson> outputs;
    }

    private static final class ItemJson
    {
        int id;
        String name;
        double qty;
        Integer fixedPrice;
    }

    private static final class PrayerJson
    {
        int libationMinLevel;
        int libationFeeGp;
        ItemRefJson jugOfWine;
        ItemRefJson sunfireSplinters;
        ItemRefJson bucketOfSlime;
        List<BoneJson> bones;
        List<AshJson> ashes;
    }

    /** A bare item reference (no quantity) used by the generated Prayer methods. */
    private static final class ItemRefJson
    {
        int id;
        String name;
